import React from 'react';

// Mock data with more details, including images
const recruitmentPipeline = {
  'Applied': [
    { id: 1, name: 'Aarav Sharma', title: 'Asst. Professor, CS', applied: '2 days ago', img: 'https://randomuser.me/api/portraits/men/32.jpg' },
    { id: 2, name: 'Sanya Verma', title: 'Lab Technician, Physics', applied: '5 days ago', img: 'https://randomuser.me/api/portraits/women/44.jpg' },
    { id: 3, name: 'Neha Reddy', title: 'Junior Librarian', applied: '1 week ago', img: 'https://randomuser.me/api/portraits/women/17.jpg' },
  ],
  'Interviewed': [
    { id: 4, name: 'Rohan Mehta', title: 'Asst. Professor, CS', applied: 'Interviewed: Yesterday', img: 'https://randomuser.me/api/portraits/men/35.jpg' },
    { id: 5, name: 'Priya Singh', title: 'Asst. Professor, CS', applied: 'Interviewed: 3 days ago', img: 'https://randomuser.me/api/portraits/women/21.jpg' },
  ],
  'Offer Made': [
    { id: 6, name: 'Karan Malhotra', title: 'Lab Technician, Physics', applied: 'Offer Made: 2 days ago', img: 'https://randomuser.me/api/portraits/men/41.jpg' },
  ],
  'Hired': [
    { id: 7, name: 'Isha Gupta', title: 'Admissions Counselor', applied: 'Hired: Yesterday', img: 'https://randomuser.me/api/portraits/women/55.jpg', hired: true },
  ],
};

const pipelineStages = Object.keys(recruitmentPipeline);

const RecruitmentPage = () => {
  return (
    <div className="flex flex-col h-full bg-background-light dark:bg-background-dark">
      {/* Header Section */}
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark flex-shrink-0">
        <div className="flex justify-between items-center mb-4">
            <div>
                <h1 className="text-2xl font-bold text-text-light dark:text-text-dark">Candidate Pipeline</h1>
                <p className="text-sm text-subtext-light">Hiring for: Assistant Professor, Computer Science</p>
            </div>
            <button className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600">
                <span className="material-icons mr-2 text-base">add</span> Add Candidate
            </button>
        </div>
        {/* Filter Bar */}
        <div className="flex items-center space-x-4">
            <div className="relative flex-grow">
                <span className="material-icons absolute left-3 top-1/2 -translate-y-1/2 text-subtext-light">search</span>
                <input type="text" placeholder="Search candidates by name..." className="w-full pl-10 pr-4 py-2 rounded-lg bg-background-light dark:bg-background-dark border-border-light dark:border-border-dark" />
            </div>
            <select className="px-4 py-2 rounded-lg bg-background-light dark:bg-background-dark border-border-light dark:border-border-dark text-sm">
                <option>All Positions</option>
            </select>
            <select className="px-4 py-2 rounded-lg bg-background-light dark:bg-background-dark border-border-light dark:border-border-dark text-sm">
                <option>All Departments</option>
            </select>
        </div>
      </header>

      {/* Kanban Board Container */}
      <div className="flex-1 p-8 flex space-x-6 overflow-x-auto">
        {pipelineStages.map(stage => (
          <div key={stage} className="bg-gray-100 dark:bg-gray-900/50 rounded-lg w-80 flex-shrink-0">
            {/* Column Header */}
            <div className="p-4">
              <h3 className="text-base font-bold text-text-light dark:text-text-dark">
                {stage} ({recruitmentPipeline[stage].length})
              </h3>
            </div>
            {/* Column Body with Candidate Cards */}
            <div className="p-4 space-y-4">
              {recruitmentPipeline[stage].map(candidate => (
                <div 
                  key={candidate.id} 
                  className={`bg-card-light dark:bg-card-dark p-4 rounded-lg shadow-md cursor-pointer hover:shadow-xl transition-shadow border-l-4 ${candidate.hired ? 'border-green-500' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex items-center space-x-3">
                      <img className="w-10 h-10 rounded-full" src={candidate.img} alt={candidate.name} />
                      <div>
                        <p className="font-bold text-text-light dark:text-text-dark">{candidate.name}</p>
                        <p className="text-sm text-subtext-light dark:text-subtext-dark">{candidate.title}</p>
                      </div>
                    </div>
                    <button className="text-subtext-light dark:text-subtext-dark">···</button>
                  </div>
                  <p className="text-xs text-subtext-light dark:text-subtext-dark mt-3">{candidate.applied}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default RecruitmentPage;
